export function resolveApiServerConfig<Options extends ApiConfig & Omit<UserConfig, 'expect'>>(
  options: Options,
  defaultPort: number,
  parentApi?: ApiConfig,
  logger?: Logger,
): ApiConfig | undefined {
  let api: ApiConfig | undefined

  if (options.ui && !options.api) {
